A set $\mathcal{U}$ is called a \textbf{universe} if the following hold:
\begin{itemize}
\item if $x\in\mathcal{U}$ and $y\in x$, then $y\in\mathcal{U}$;
\item if $x\in\mathcal{U}$, then $\{x\}\in\mathcal{U}$;
\item if $x\in\mathcal{U}$, then $\mathcal{P}(x)=\{y\mid y\subseteq 
x\}\in\mathcal{U}$;
\item if $I\in\mathcal{U}$ and $(x_i)_{i\in I}$ is an $I$-indexed family of 
elements of $\mathcal{U}$, then $\bigcup_{i\in I} x_i\in\mathcal{U}$;
\item $\mathbb{N}\in\mathcal{U}$, where $\mathbb{N}=\{0,1,\dots\}$ and for 
all $n\in\mathbb{N}$, $n=\{0,1,\dots, n-1\}$.
\qedhere
\end{itemize}

\label{conv:size}
A set or other mathematical structure (group, category, etc.) 
is said to be:
\begin{itemize}
\item \textbf{small} if it is in $\mathcal{U}_1$;
\item \textbf{large} if it is in $\mathcal{U}_2$;
\item \textbf{huge} if it is in $\mathcal{U}_3$.
\end{itemize}
Sets and other mathematical structures are often assumed to be small by 
default, even when we do not say so explicitly.

A category (or a 2-category) is said to be:
\begin{itemize}
\item \textbf{locally small} if it is large and locally in $\mathcal{U}_1$;
\item \textbf{locally large} if it is huge and locally in $\mathcal{U}_2$.\qedhere
\end{itemize}

\label{def:Sigma_alg}
Let $\Sigma$ be a graded set.
\begin{enumerate}
\item A \textbf{$\Sigma$-algebra} is a set $A$ equipped with,
for each $n\in\mathbb{N}$ and $\sigma\in\Sigma_n$,
a function ${[\![\sigma]\!]}^A\colon A^n\longrightarrow A$
called the \textbf{interpretation of $\sigma$}.
We write such a $\Sigma$-algebra as 
$(A,({[\![\sigma]\!]}^A)_{n\in\mathbb{N},\sigma\in\Sigma_n})$
or simply $(A,{[\![-]\!]}^A)$.
We often omit the superscript in ${[\![-]\!]}^A$.
\item If $(A,{[\![-]\!]}^A)$
and $(B,{[\![-]\!]}^{B})$
are $\Sigma$-algebras,
then a \textbf{$\Sigma$-homomorphism} from 
$(A,{[\![-]\!]}^A)$ to 
$(B,{[\![-]\!]}^{B})$
is a function $f\colon A\longrightarrow B$ such that for any $n\in\mathbb{N}$,
$\sigma\in\Sigma_n$ and $a_1,\dots,a_n\in A$,
\[
f({[\![\sigma]\!]}^A(a_1,\dots,a_n))={[\![\sigma]\!]}^B(f(a_1),\dots,f(a_n))
\]
holds (that is, the diagram
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$A^n$};
      \node (TR) at (3,2)  {$B^n$};
      \node (BL) at (0,0) {$A$};
      \node (BR) at (3,0) {$B$};

      \draw[->] (TL) to node[auto,labelsize](T) {$f^n$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {${[\![\sigma]\!]}^{B}$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {${[\![\sigma]\!]}^A$} (BL);
      \draw[->] (BL) to node[auto,labelsize](B) {$f$} (BR);

\end{tikzpicture} 
\]
commutes).\qedhere
\end{enumerate}

\label{defn:univ_alg_pres_eq_thy}
A \textbf{presentation of an equational theory} ${{\langle\, \Sigma\, |\, E \,\rangle}}$ 
is a pair consisting of:
\begin{itemize}
\item a graded set $\Sigma$ of \textbf{basic operations}, 
and
\item a graded set $E\subseteq T(\Sigma)\times T(\Sigma)$
of \textbf{equational axioms}.\qedhere
\end{itemize}

\label{defn:univ_alg_model}
Let ${{\langle\, \Sigma\, |\, E \,\rangle}}$ be a presentation of an equational theory.
\begin{enumerate}
\item A \textbf{model of ${{\langle\, \Sigma\, |\, E \,\rangle}}$} is a $\Sigma$-algebra
$(A,{[\![-]\!]})$
such that for any $t\approx_n s\in E$,
${[\![t]\!]}={[\![s]\!]}$ holds.
\item A \textbf{homomorphism}
between models of ${{\langle\, \Sigma\, |\, E \,\rangle}}$ is just
a $\Sigma$-homomorphism between the corresponding
$\Sigma$-algebras.\qedhere
\end{enumerate}

\label{def:eq_logic}
Let ${{\langle\, \Sigma\, |\, E \,\rangle}}$ be a presentation of an equational theory.
\begin{enumerate}
\item Define the set of \textbf{${{\langle\, \Sigma\, |\, E \,\rangle}}$-proofs} inductively
by the following inference rules.
Every ${{\langle\, \Sigma\, |\, E \,\rangle}}$-proof is a finite rooted tree whose vertices 
are labelled by $\Sigma$-equations.
\begin{center}
\AxiomC{}
\LeftLabel{(\sc{Ax})\ }
\RightLabel{\ (if $t\approx_n s \in E$)}
\UnaryInfC{$t\approx_n s$}
\DisplayProof


\bottomAlignProof
\AxiomC{}
\LeftLabel{(\sc{Refl})\ }
\UnaryInfC{$t\approx_n t$}
\DisplayProof
\quad
\bottomAlignProof
\AxiomC{$t\approx_n s $}
\LeftLabel{(\sc{Sym})\ }
\UnaryInfC{$s\approx_n t$}
\DisplayProof
\quad
\bottomAlignProof
\AxiomC{$t\approx_n s$}
\AxiomC{$s\approx_n u$}
\LeftLabel{(\sc{Trans})\ }
\BinaryInfC{$t\approx_n u$}
\DisplayProof

\bottomAlignProof
\AxiomC{$s\approx_k s'$}
\AxiomC{$t_1\approx_n t'_1$}
\AxiomC{$\cdots$}
\AxiomC{$t_k\approx_n t'_k$}
\LeftLabel{(\sc{Cong})\ }
\QuaternaryInfC{$s[x^{(k)}_1 \mapsto t_1, \dots, x^{(k)}_k\mapsto t_k]\approx_n 
s'[x^{(k)}_1 \mapsto t'_1, \dots, x^{(k)}_k\mapsto t'_k]$}
\DisplayProof
\end{center}
\item A $\Sigma$-equation 
$t\approx_n s\in T(\Sigma)\times T(\Sigma)$ is called an
\textbf{equational theorem of ${{\langle\, \Sigma\, |\, E \,\rangle}}$} if there exists 
a ${{\langle\, \Sigma\, |\, E \,\rangle}}$-proof whose root is labelled by $t\approx_n s$.
We write \[
{{\langle\, \Sigma\, |\, E \,\rangle}}\vdash t\approx_n s\]
to mean that $t\approx_n s$ is 
an equational theorem of ${{\langle\, \Sigma\, |\, E \,\rangle}}$, and denote by 
$\overline{E}\subseteq T(\Sigma)\times T(\Sigma)$ the 
graded set of all equational theorems of ${{\langle\, \Sigma\, |\, E \,\rangle}}$.
\qedhere
\end{enumerate}

\label{thm:eq_logic_sound_complete}
Let ${{\langle\, \Sigma\, |\, E \,\rangle}}$ be a presentation of an equational theory.
\begin{enumerate}
\item (Soundness) Let $t\approx_n s\in T(\Sigma)\times T(\Sigma)$.
If ${{\langle\, \Sigma\, |\, E \,\rangle}}\vdash t\approx_n s$ then ${{\langle\, \Sigma\, |\, E \,\rangle}}\vDash 
t\approx_n s$.
\item (Completeness) Let $t\approx_n s\in T(\Sigma)\times T(\Sigma)$.
If ${{\langle\, \Sigma\, |\, E \,\rangle}}\vDash t\approx_n s$ then ${{\langle\, \Sigma\, |\, E \,\rangle}}\vdash 
t\approx_n s$.
\end{enumerate}

\label{def:endo_clone}
Let $A$ be a set.
Define the clone $\mathsf{End}(A)=({\langle A, A\rangle},p,\circ)$

as follows:
\begin{description}
\item[(CD1)] for each $n\in\mathbb{N}$, let ${\langle A, A\rangle}_n$ be the set of all
functions from $A^n$ to $A$; 
\item[(CD2)] for each $n\in\mathbb{N}$ and $i\in\{1,\dots,n\}$,
let $p^{(n)}_i$ be the $i$-th projection 
$A^n\longrightarrow A$, $(a_1,\dots,a_n)\longmapsto a_i$;
\item[(CD3)] for each $k,n\in\mathbb{N}$, $g\colon A^k\longrightarrow A$ and
$f_1,\dots,f_k\colon A^n\longrightarrow A$, 
let $g\circ^{(n)}_k(f_1,\dots,f_k)$ be the function
$(a_1,\dots,a_n)\longmapsto g(f_1(a_1,\dots,a_n),\dots,f_k(a_1,\dots,a_n))$,
that is, the following composite:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (1) at (0,0)  {$A^n$};
      \node (2) at (3,0)  {$A^k$};
      \node (3) at (5,0) {$A.$};

      \draw[->] (1) to node[auto,labelsize]{$\langle f_1,\dots,f_k\rangle$} (2);
      \draw[->] (2) to node[auto,labelsize] {$g$} (3);

\end{tikzpicture} 
\]
\end{description}
It is straightforward to check the axioms (CA1)--(CA3).

\label{def:clone_hom}
Let $\mathsf{T}=(T,p,\circ)$ and $\mathsf{T'}=(T',p',\circ')$ be 
clones.
A \textbf{clone homomorphism} from $\mathsf{T}$ to $\mathsf{T'}$
is a morphism of graded sets (Definition~\ref{def:graded_set}) 
$h\colon T\longrightarrow T'$ which preserves the structure of clones;
precisely,
\begin{itemize}
\item for each $n\in\mathbb{N}$ and $i\in\{1,\dots,n\}$, $h_n(p^{(n)}_i)=p'^{(n)}_i$;
\item for each $k,n\in\mathbb{N}$, $\phi\in T_k$ and $\theta_1,\dots,\theta_k\in T_n$,
\[
h_n\big(\phi\circ^{(n)}_k(\theta_1,\dots,\theta_k)\big)=
h_k(\phi)\circ'^{(n)}_k \big(h_n(\theta_1),\dots,h_n(\theta_k)\big).\qedhere
\]
\end{itemize}

\label{def:clone_mod_hom}
Let $\mathsf{T}$ be a clone, and $(A,\alpha)$ and $(B,\beta)$ be models of 
$\mathsf{T}$.
A \textbf{homomorphism} from $(A,\alpha)$ to $(B,\beta)$ is a function 
$f\colon A\longrightarrow B$ making the following diagram of 
morphisms of graded sets commute:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$T$};
      \node (TR) at (3,2)  {${\langle A, A\rangle}$};
      \node (BL) at (0,0) {${\langle B, B\rangle}$};
      \node (BR) at (3,0) {${\langle A, B\rangle}.$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\alpha$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {${\langle A, f\rangle}$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$\beta$} (BL);
      \draw[->] (BL) to node[auto,swap,labelsize](B) {${\langle f, B\rangle}$} (BR);

\end{tikzpicture} \qedhere
\]

\label{prop:free_clone}
Let $\Sigma$ be a graded set.
The clone $\mathsf{T}(\Sigma)$ is the free clone generated from the 
graded set $\Sigma$. 
That is, the morphism of graded sets $\eta_\Sigma\colon \Sigma\longrightarrow
T(\Sigma)$, defined by 
$(\eta_\Sigma)_n(\sigma)=\sigma(x^{(n)}_1,\dots,x^{(n)}_n)$ for each $n\in\mathbb{N}$ 
and $\sigma\in\Sigma_n$,
satisfies the following property:
given any clone $\mathsf{S}=(S,p,\circ)$ and any morphism of 
graded sets $f\colon \Sigma\longrightarrow S$, there exists a 
unique clone homomorphism $g\colon \mathsf{T}(\Sigma)\longrightarrow \mathsf{S}$
such that $g\circ \eta_\Sigma=f$.
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$\Sigma$};
      \node (TR) at (3,1)  {${T}(\Sigma)$};
      \node (BR) at (3,-1) {$S$};
      \node (B) at (1.5,-1.8) {{(graded sets)}};

      \draw[->] (TL) to node[auto,labelsize](T) {$\eta_\Sigma$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$g$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$f$} (BR);

\end{tikzpicture} 
\qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TR) at (3,1)  {$\mathsf{T}(\Sigma)$};
      \node (BR) at (3,-1) {$\mathsf{S}$};
      \node (B) at (3,-1.8) {(clones)};

      \draw[->,dashed]  (TR) to node[auto,labelsize] {$g$} (BR);

\end{tikzpicture} 
\]

\label{prop:quotient_clone}
Let ${{\langle\, \Sigma\, |\, E \,\rangle}}$ be a presentation of an equational theory.
The clone homomorphism $q\colon \mathsf{T}(\Sigma)\longrightarrow 
\mathsf{T}^{{\langle\, \Sigma\, |\, E \,\rangle}}$, defined by $q_n(\theta)=[\theta]_{\overline{E}}$
for each $n\in\mathbb{N}$ and $\theta\in T(\Sigma)_n$, satisfies the following 
property: given any clone $\mathsf{S}=(S,p,\circ)$ and a clone homomorphism 
$g\colon \mathsf{T}(\Sigma)\longrightarrow \mathsf{S}$ such that for any 
$t\approx_n s\in E$, $g_n(t)=g_n(s)$, there exists a unique
clone homomorphism $h\colon 
\mathsf{T}^{{\langle\, \Sigma\, |\, E \,\rangle}}\longrightarrow\mathsf{S}$
such that $h\circ q=g$.
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$\mathsf{T}(\Sigma)$};
      \node (TR) at (3,1)  {$\mathsf{T}^{{\langle\, \Sigma\, |\, E \,\rangle}}$};
      \node (BR) at (3,-1) {$\mathsf{S}$};

      \draw[->] (TL) to node[auto,labelsize](T) {$q$} (TR);
      \draw[->,dashed]  (TR) to node[auto,labelsize] {$h$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$g$} (BR);

\end{tikzpicture} 
\]

A \textbf{strongly regular presentation of an equational theory}
${{\langle\, \Sigma\, |\, E \,\rangle}}$ is a pair consisting of:
\begin{itemize}
\item a graded set $\Sigma$ of \textbf{basic operations}, and
\item a graded set $E\subseteq T_\mathrm{SR}(\Sigma)\times T_\mathrm{SR}(\Sigma)$ of 
(strongly regular) \textbf{equational axioms}.\qedhere
\end{itemize}

\label{def:non_symm_op}
A \textbf{non-symmetric operad} $\mathsf{T}$ consists of:
\begin{description}
\item[(ND1)] a graded set $T=(T_n)_{n\in\mathbb{N}}$;
\item[(ND2)] an element ${\mathrm{id}_{}}\in T_1$;
\item[(ND3)] for each $k,n_1,\dots,n_k\in \mathbb{N}$, a function
(we omit the sub- and superscripts)
\[
\circ\colon T_k\times T_{n_1}\times\dots\times T_{n_k}\longrightarrow 
T_{n_1+\dots+ n_k}
\]
whose action we write as $(\phi,\theta_1,\dots,\theta_k)\longmapsto \phi\circ 
(\theta_1,\dots,\theta_k)$
\end{description}
satisfying the following equations:
\begin{description}
\item[(NA1)] for each $n\in\mathbb{N}$ and $\theta\in T_n$,
\[
{\mathrm{id}_{}}\circ (\theta)=\theta;
\]
\item[(NA2)] for each $n\in\mathbb{N}$ and $\theta\in T_n$,
\[
\theta\circ ({\mathrm{id}_{}},\dots,{\mathrm{id}_{}}) = \theta;
\] 
\item[(NA3)] for each $l,\ k_1,\dots,k_l,\ 
n_{1,1},\dots,n_{1,k_1},\dots,n_{l,1},
\dots,n_{l,k_l}\in\mathbb{N}$, \ $\psi\in T_l$, \ $\phi_1\in T_{k_1}, \dots, \phi_l\in 
T_{k_l}$, \ $\theta_{1,1}\in T_{n_{1,1}},\dots,\theta_{1,k_1}\in T_{n_{1,k_1}},
\dots, \theta_{l,1}\in T_{n_{l,1}},\dots,$ $\theta_{l,k_l}\in T_{n_{l, k_l}}$,
\begin{multline*}
\psi\circ\big(\phi_1\circ (\theta_{1,1},\dots,\theta_{1,k_1}),\ \dots\ ,
\phi_l\circ (\theta_{l,1},\dots,\theta_{l,k_l}) \big)\\
=
\big(\psi\circ 
(\phi_1,\dots,\phi_l)\big)\circ(\theta_{1,1},\dots,\theta_{1,k_1},\ \dots,\ 
\theta_{l,1},\dots,\theta_{l,k_l}).
\end{multline*}
\end{description}
Such a non-symmetric operad is written as $\mathsf{T}=(T,{\mathrm{id}_{}},\circ)$.

Let $A$ be a set. 
Define the non-symmetric operad $\mathsf{End}_\mathbf{Set}(A)=({\langle A, A\rangle},{\mathrm{id}_{}},\circ)$ 
as follows:
\begin{description}
\item[(ND1)] for each $n\in\mathbb{N}$, let ${\langle A, A\rangle}_n$
be the set of all functions from $A^n$ to $A$;
\item[(ND2)] the element ${\mathrm{id}_{}}\in{\langle A, A\rangle}$ is the identity function on 
$A$;
\item[(ND3)] for each $k,n_1,\dots,n_k\in\mathbb{N}$, $g\colon A^k\longrightarrow A$,
$f_1\colon A^{n_1}\longrightarrow A,\dots,f_k\colon A^{n_k}\longrightarrow A$,
let $g\circ (f_1,\dots,f_k)$ be the following composite: 
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (1) at (-1,0)  {$A^{n_1+\dots+n_k}$};
      \node (2) at (3,0)  {$A^{k}$};
      \node (3) at (5,0) {$A.$};

      \draw[->] (1) to node[auto,labelsize]{$f_1\times\dots\times 
      f_k$} (2);
      \draw[->] (2) to node[auto,labelsize] {$g$} (3);

\end{tikzpicture} \qedhere
\]
\end{description}

Let $A$ be an abelian group. 
Define the non-symmetric operad $\mathsf{End}_\mathbf{Ab}(A)=({\langle A, A\rangle},{\mathrm{id}_{}},\circ)$ 
as follows:
\begin{description}
\item[(ND1)] for each $n\in\mathbb{N}$, let ${\langle A, A\rangle}_n$
be the set of all group homomorphisms from $A^{\otimes n}$ to $A$;
\item[(ND2)] the element ${\mathrm{id}_{}}\in{\langle A, A\rangle}$ is the identity homomorphism 
on $A$;
\item[(ND3)] for each $k,n_1,\dots,n_k\in\mathbb{N}$, $g\colon A^{\otimes k} 
\longrightarrow A$,
$f_1\colon A^{\otimes n_1}\longrightarrow A,\dots,
f_k\colon A^{\otimes n_k}\longrightarrow A$,
let $g\circ (f_1,\dots,f_k)$ be the following composite: 
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (1) at (-1,0)  {$A^{\otimes (n_1+\dots+n_k)}$};
      \node (2) at (3,0)  {$A^{\otimes k}$};
      \node (3) at (5,0) {$A.$};

      \draw[->] (1) to node[auto,labelsize]{$f_1\otimes\dots\otimes 
      f_k$} (2);
      \draw[->] (2) to node[auto,labelsize] {$g$} (3);

\end{tikzpicture} \qedhere
\]
\end{description}

\label{def:monad}
Let $\mathcal{C}$ be a large category. 
\begin{enumerate}
\item 
A \textbf{monad on $\mathcal{C}$} consists of:
\begin{itemize}
\item a functor $T\colon \mathcal{C}\longrightarrow \mathcal{C}$;
\item a natural transformation $\eta\colon {\mathrm{id}_{\mathcal{C}}}\longrightarrow T$ 
(called the \textbf{unit});
\item a natural transformation $\mu\colon T\circ T\longrightarrow T$
(called the \textbf{multiplication}),
\end{itemize}
making the following diagrams commute:
\begin{equation*}

\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {${\mathrm{id}_{\mathcal{C}}}\circ T$};
      \node (TR) at (2,2)  {$T\circ T$};
      \node (BR) at (2,0) {$T$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\eta\circ T$} (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$\mu$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {${\mathrm{id}_{T}}$} (BR);

\end{tikzpicture} 
\qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$T\circ {\mathrm{id}_{\mathcal{C}}}$};
      \node (TR) at (2,2)  {$T\circ T$};
      \node (BR) at (2,0) {$T$};

      \draw[->] (TL) to node[auto,labelsize](T) {$T\circ \eta$} (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$\mu$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {${\mathrm{id}_{T}}$} (BR);

\end{tikzpicture} 
\qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$T\circ T\circ T$};
      \node (TR) at (3,2)  {$T\circ T$};
      \node (BL) at (0,0) {$T\circ T$};
      \node (BR) at (3,0) {$T$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\mu\circ T$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$\mu$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$T\circ \mu$} (BL);
      \draw[->] (BL) to node[auto,labelsize](B) {$\mu$} (BR);

\end{tikzpicture} 
\end{equation*}
\item Let $\mathsf{T}=(T,\eta,\mu)$ and $\mathsf{T'}=(T',\eta',\mu')$
be monads on $\mathcal{C}$.
A \textbf{morphism of monads on $\mathcal{C}$} from $\mathsf{T}$ to $\mathsf{T'}$
is a natural transformation $\alpha\colon T\longrightarrow T'$
which commutes with the units and multiplications. 
\end{enumerate}
We denote the category of monads on $\mathcal{C}$ by ${\mathbf{Mnd}(\mathcal{C})}$.

\label{def:EM_alg}
Let $\mathcal{C}$ be a large category and $\mathsf{T}=(T,\eta,\mu)$ be a monad on 
$\mathcal{C}$.
\begin{enumerate}
\item 
An \textbf{Eilenberg--Moore algebra of $\mathsf{T}$}
consists of:
\begin{itemize}
\item an object $C\in\mathcal{C}$;
\item a morphism $\gamma\colon TC\longrightarrow C$ in $\mathcal{C}$,
\end{itemize}
making the following diagrams commute:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$C$};
      \node (TR) at (2,2)  {$TC$};
      \node (BR) at (2,0)  {$C$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\eta_C$} (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$\gamma$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {${\mathrm{id}_{C}}$} (BR);

\end{tikzpicture} 
\qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$TTC$};
      \node (TR) at (2,2)  {$TC$};
      \node (BL) at (0,0) {$TC$};
      \node (BR) at (2,0) {$C.$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\mu_C$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$\gamma$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$T\gamma$} (BL);
      \draw[->] (BL) to node[auto,labelsize](B) {$\gamma$} (BR);

\end{tikzpicture} 
\end{equation*}
\item Let $(C,\gamma)$ and $(C',\gamma')$ be Eilenberg--Moore algebras of 
$\mathsf{T}$.
A \textbf{homomorphism} from $(C,\gamma)$ to $(C',\gamma')$ 
is a morphism $f\colon C\longrightarrow C'$ in $\mathcal{C}$
making the following diagram commute:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$TC$};
      \node (TR) at (2,2)  {$TC'$};
      \node (BL) at (0,0) {$C$};
      \node (BR) at (2,0) {$C'.$};

      \draw[->] (TL) to node[auto,labelsize](T) {$Tf$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$\gamma'$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$\gamma$} (BL);
      \draw[->] (BL) to node[auto,labelsize](B) {$f$} (BR);

\end{tikzpicture}
\]
\end{enumerate}
The category of all Eilenberg--Moore algebras of $\mathsf{T}$ and their
homomorphism is celled the \textbf{Eilenberg--Moore category of $\mathsf{T}$},
and is denoted by $\mathcal{C}^\mathsf{T}$.

\begin{enumerate}
\item Let $\mathcal{C}$ and $\mathcal{D}$ be categories, and $F,G\colon 
\mathcal{C}\longrightarrow \mathcal{D}$ be functors.
A natural transformation $\alpha\colon F\longrightarrow G$
is called \textbf{cartesian} if and only if all naturality squares of $\alpha$
are pullback squares;
that is, if and only if 
for any morphism $f\colon C\longrightarrow C'$ in $\mathcal{C}$, 
the square 
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$FC$};
      \node (TR) at (2,2)  {$GC$};
      \node (BL) at (0,0) {$FC'$};
      \node (BR) at (2,0) {$GC'$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\alpha_C$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$Gf$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$Ff$} (BL);
      \draw[->] (BL) to node[auto,labelsize](B) {$\alpha_{C'}$} (BR);

\end{tikzpicture}
\]
is a pullback of $Gf$ and $\alpha_{C'}$.
\item Let $\mathcal{C}$ be a category with all pullbacks.
A monad $\mathsf{S}=(S,\eta,\mu)$ on $\mathcal{C}$ is called 
\textbf{cartesian} if and only if the functor $S$ preserves pullbacks,
and $\eta$ and $\mu$ are cartesian.\qedhere
\end{enumerate}

\label{def:S_operad}
Let $\mathcal{C}$ be a large category with all finite limits 
and $\mathsf{S}=(S,\eta,\mu)$ a cartesian monad on $\mathcal{C}$.
\begin{enumerate}
\item An \textbf{$\mathsf{S}$-operad} is a monoid object in the monoidal 
category
$(\mathcal{C}/S1,I,\otimes)$ introduced above; see Definition~\ref{def:monoid_obj}
for the definition of monoid object in a monoidal category.
\item A \textbf{morphism of $\mathsf{S}$-operads} is a homomorphism 
of monoid objects; see Definition~\ref{def:monoid_obj} again.
\end{enumerate}
We denote the category of $\mathsf{S}$-operads by ${{\mathsf{S}}\mhyphen\mathbf{Opd}}$;
by definition it is identical to the category ${\mathbf{Mon}(\mathcal{C}/S1)}$ of monoid
objects in $\mathcal{C}/S1$.

\label{def:S-operad_model}
Let $\mathcal{C}$ be a large category with finite limits, $\mathsf{S}=(S,\eta,\mu)$
a cartesian monad on $\mathcal{C}$, and $\mathsf{T}=(T,e,m)$ an 
$\mathsf{S}$-operad.
\begin{enumerate}
\item A \textbf{model of $\mathsf{T}$} consists of:
\begin{itemize}
\item an object $C\in\mathcal{C}$;
\item a morphism $\gamma\colon T\ast C\longrightarrow C$ in $\mathcal{C}$,
\end{itemize}
making the following diagrams commute:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$I\ast C$};
      \node (TR) at (2,2)  {$T\ast C$};

      \node (BR) at (2,0) {${C}$};

      \draw[->]  (TL) to node[auto,labelsize] {$e\ast C$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$\gamma$} (BR);
      \draw[->] (TL) to node[auto,swap,labelsize](B) {$\cong$} (BR);

\end{tikzpicture} 
\qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$(T\otimes T)\ast C$};
      \node (TR) at (5,2)  {$T\ast C$};
      \node (BL) at (0,0) {$T\ast (T\ast C)$};
      \node (BM) at (3,0) {$T\ast C$};
      \node (BR) at (5,0) {${C},$};

      \draw[->]  (TL) to node[auto,swap,labelsize] {$\cong$} (BL);
      \draw[->]  (TL) to node[auto,labelsize] {$m\ast C$} (TR);
      \draw[->]  (BL) to node[auto,labelsize] {$T\ast \gamma$} (BM);
      \draw[->]  (BM) to node[auto,labelsize] {$\gamma$} (BR);
      \draw[->]  (TR) to node[auto,labelsize](B) {$\gamma$} (BR);

\end{tikzpicture} 
\end{equation*}
where the arrows labelled with $\cong$ refer to the isomorphisms 
provided by the pseudo action.
\item Let $(C,\gamma)$ and $(C',\gamma')$ be models of $\mathsf{T}$. A 
\textbf{homomorphism from $(C,\gamma)$ to 
$(C',\gamma')$}
is a morphism $f\colon C\longrightarrow C'$ in $\mathcal{C}$ making the 
following diagram commute:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$T\ast C$};
      \node (TR) at (3,2)  {$T\ast C'$};
      \node (BL) at (0,0) {$C$};
      \node (BR) at (3,0) {$C'.$};

      \draw[->]  (TL) to node[auto,swap,labelsize] {$\gamma$} (BL);
      \draw[->]  (TL) to node[auto,labelsize] {$T\ast f$} (TR);
      \draw[->]  (BL) to node[auto,labelsize] {${f}$} (BR);
      \draw[->]  (TR) to node[auto,labelsize](B) {$\gamma'$} (BR);

\end{tikzpicture} \qedhere
\] 
\end{enumerate}

\label{def:monoid_obj}
Let $\mathcal{M}=(\mathcal{M},I,\otimes)$ be a large monoidal category.
\begin{enumerate}
\item 
A \textbf{monoid object in $\mathcal{M}$} (or simply a \textbf{monoid in 
$\mathcal{M}$}) is a triple $\mathsf{T}=(T,e,m)$ 
consisting of
an object $T$ in $\mathcal{M}$, and morphisms $e\colon I\longrightarrow T$
and $m\colon T\otimes T\longrightarrow T$ in $\mathcal{M}$,
such that the following diagrams commute:
\begin{equation*}

\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$I\otimes T$};
      \node (TR) at (2,1)  {$T\otimes T$};
      \node (BR) at (2,-1) {$T$};

      \draw[->] (TL) to node[auto,labelsize](T) {$e\otimes T$} (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$m$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {$\cong$} (BR);

\end{tikzpicture} 
\qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$T\otimes I$};
      \node (TR) at (2,1)  {$T\otimes T$};
      \node (BR) at (2,-1) {$T$};

      \draw[->] (TL) to node[auto,labelsize](T) {$T\otimes e$} (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$m$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {$\cong$} (BR);

\end{tikzpicture} 
\end{equation*}
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$(T\otimes T)\otimes T$};
      \node (TR) at (5,2)  {$T\otimes T$};
      \node (BL) at (0,0) {$T\otimes (T\otimes T)$};
      \node (BM) at (3,0) {$T\otimes T$};
      \node (BR) at (5,0) {$T$};

      \draw[->] (TL) to node[auto,labelsize](T) {$m\otimes T$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$m$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$\cong$} (BL);
      \draw[->]  (BL) to node[auto,labelsize] {$T\otimes m$} (BM);
      \draw[->] (BM) to node[auto,labelsize](B) {$m$} (BR);

\end{tikzpicture} 
\end{equation*}
(Recall that the arrows labelled with $\cong$ are the 
suitable instances of structural isomorphisms 
of $\mathcal{M}$.)
\item Let $\mathsf{T}=(T,e,m)$ and $\mathsf{T'}=(T',e',m')$ be monoid objects in
$\mathcal{M}$. 
A \textbf{homomorphism} from $\mathsf{T}$ to $\mathsf{T'}$ is a morphism
$f\colon T\longrightarrow T'$ in $\mathcal{M}$ such that the following diagrams
commute:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (1,2)  {$I$};

      \node (BL) at (0,0) {$T$};
      \node (BR) at (2,0) {$T'$};

      \draw[->]  (TL) to node[auto,swap,labelsize] {$e$} (BL);
      \draw[->]  (BL) to node[auto,labelsize] {$f$} (BR);
      \draw[->] (TL) to node[auto,labelsize](B) {$e'$} (BR);

\end{tikzpicture} 
\qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$T\otimes T$};
      \node (TR) at (3,2)  {$T'\otimes T'$};
      \node (BL) at (0,0) {$T$};
      \node (BR) at (3,0) {$T'$};

      \draw[->]  (TL) to node[auto,swap,labelsize] {$m$} (BL);
      \draw[->]  (TL) to node[auto,labelsize] {$f\otimes f$} (TR);
      \draw[->]  (BL) to node[auto,labelsize] {$f$} (BR);
      \draw[->]  (TR) to node[auto,labelsize](B) {$m'$} (BR);

\end{tikzpicture} 
\end{equation*}
\end{enumerate}
The category of all monoid objects in $\mathcal{M}$ and homomorphisms 
is denoted by ${\mathbf{Mon}(\mathcal{M})}$.

The \textbf{substitution monoidal structure} on $[\mathbf{F},\mathbf{Set}]$ is defined as 
follows:
\begin{itemize}
\item The unit object is $I=\mathbf{F}([1],-)\colon \mathbf{F}\longrightarrow\mathbf{Set}$.
\item Given $X,Y\colon \mathbf{F}\longrightarrow\mathbf{Set}$, their monoidal product 
$Y\otimes X\colon \mathbf{F}\longrightarrow\mathbf{Set}$ maps $[n]\in\mathbf{F}$ to 
\begin{equation}
\label{eqn:subst_tensor_F}
(Y\otimes X)_n=\int^{[k]\in\mathbf{F}} Y_k\times (X_n)^k.
\end{equation}
\end{itemize}

Let $\mathbf{P}$ be the category defined as follows:
\begin{itemize}
\item The set of objects is the same as $\mathbf{F}$: ${\mathrm{ob}(\mathbf{P})}=\{\,[n]\mid 
n\in\mathbb{N}\,\}$ where $[n]=\{1,\dots,n\}$.
\item A morphism is any \emph{bijective} function.\qedhere
\end{itemize}

\label{def:subst_monoidal_P}
The \textbf{substitution monoidal structure} on $[\mathbf{P},\mathbf{Set}]$ is defined as 
follows:
\begin{itemize}
\item The unit object is $I=\mathbf{P}([1],-)\colon\mathbf{P}\longrightarrow\mathbf{Set}$.
\item Given $X,Y\colon\mathbf{P}\longrightarrow\mathbf{Set}$, their monoidal product 
$Y\otimes X\colon \mathbf{P}\longrightarrow\mathbf{Set}$ maps $[n]\in\mathbf{P}$ to
\begin{equation*}
(Y\otimes X)_n
=\int^{[k]\in\mathbf{P}} 
Y_k\times 
(X^{\circledast k})_n,
\end{equation*}
where 
\[
(X^{\circledast k})_n=\int^{[n_1],\dots,[n_k]\in\mathbf{P}} 
\mathbf{P}([n_1+\dots+n_k],[n])\times 
X_{n_1}\times\dots\times X_{n_k}.\qedhere
\]
\end{itemize}

Let $\mathbf{N}$ be the category defined as follows:
\begin{itemize}
\item The set of objects is the same as $\mathbf{F}$ and $\mathbf{P}$.
\item There are only identity morphisms in $\mathbf{N}$.\qedhere
\end{itemize}

The \textbf{substitution monoidal structure} on $[\mathbf{N},\mathbf{Set}]$ is defined as 
follows:
\begin{itemize}
\item The unit object is $I=\mathbf{N}([1],-)\colon \mathbf{N}\longrightarrow \mathbf{Set}$.
\item Given $X,Y\colon \mathbf{N}\longrightarrow\mathbf{Set}$, their monoidal product
$Y\otimes X\colon\mathbf{N}\longrightarrow\mathbf{Set}$ maps $[n]\in\mathbf{N}$ to 
\[
(Y\otimes X)_n=\coprod_{[k]\in\mathbf{N}} 
Y_k\times\bigg(\coprod_{\substack{[n_1],\dots,[n_k]\in\mathbf{N}\\n_1+\dots+n_k=n}}
X_{n_1}\times\dots\times X_{n_k}\bigg).\qedhere
\]
\end{itemize}

\label{def:enrichment}
Let $\mathcal{M}=(\mathcal{M},I,\otimes)$ be a large monoidal category.
An \textbf{enrichment over $\mathcal{M}$} consists of:
\begin{itemize}
\item  a large category $\mathcal{C}$;
\item a functor 
${\langle -, -\rangle}\colon\mathcal{C}^{\mathrm{op}}\times\mathcal{C}\longrightarrow\mathcal{M}$;
\item a natural transformation $(j_C\colon 
I\longrightarrow{\langle C, C\rangle})_{C\in\mathcal{C}}$;
\item a natural transformation 
$(M_{A,B,C}\colon{\langle B, C\rangle}\otimes{\langle A, B\rangle}
\longrightarrow{\langle A, C\rangle})_{A,B,C\in\mathcal{C}}$,
\end{itemize}
making the following diagrams commute for all $A,B,C,D\in\mathcal{C}$:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$I\otimes{\langle A, B\rangle}$};
      \node (TR) at (4,1)  {${\langle B, B\rangle}\otimes{\langle A, B\rangle}$};
      \node (BR) at (4,-1) {${\langle A, B\rangle}$};

      \draw[->] (TL) to node[auto,labelsize](T) {$j_B\otimes{\langle A, B\rangle}$} 
      (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$M_{A,B,B}$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {$\cong$} (BR);

\end{tikzpicture} 
\quad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {${\langle A, B\rangle}\otimes I$};
      \node (TR) at (4,1)  {${\langle A, B\rangle}\otimes{\langle A, A\rangle}$};
      \node (BR) at (4,-1) {${\langle A, B\rangle}$};

      \draw[->] (TL) to node[auto,labelsize](T) {${\langle A, B\rangle}\otimes j_A$} 
      (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$M_{A,A,B}$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {$\cong$} (BR);

\end{tikzpicture} 
\end{equation*}
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$({\langle C, D\rangle}\otimes {\langle B, C\rangle})\otimes 
      {\langle A, B\rangle}$};
      \node (TR) at (9,1)  {${\langle B, D\rangle}\otimes{\langle A, B\rangle}$};
      \node (BL) at (0,-1) 
      {${\langle C, D\rangle}\otimes({\langle B, C\rangle}\otimes{\langle A, B\rangle})$};
      \node (BM) at (6,-1) {${\langle C, D\rangle}\otimes{\langle A, C\rangle}$};
      \node (BR) at (9,-1) {${\langle A, D\rangle}.$};

      \draw[->] (TL) to node[auto,labelsize](T) 
      {$M_{B,C,D}\otimes{\langle A, B\rangle}$} 
      (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$M_{A,B,D}$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$\cong$} (BL);
      \draw[->]  (BL) to node[auto,labelsize] {${\langle C, D\rangle}\otimes 
      M_{A,B,C}$} (BM);
      \draw[->] (BM) to node[auto,labelsize](B) {$M_{A,C,D}$} (BR);

\end{tikzpicture} 
\end{equation*}
We say that $(\mathcal{C},{\langle -, -\rangle},j,M)$ is an enrichment over $\mathcal{M}$,
or that $({\langle -, -\rangle},j,M)$ is an enrichment of $\mathcal{C}$ over $\mathcal{M}$.

\label{def:enrich_model}
Let $\mathcal{M}=(\mathcal{M},I,\otimes)$ be a large monoidal category, 
$\mathsf{T}=(T,e,m)$ be a monoid object in $\mathcal{M}$, 
$\mathcal{C}$ be a large category, and ${\langle -, -\rangle}=({\langle -, -\rangle},j,M)$ be an
enrichment of $\mathcal{C}$ over $\mathcal{M}$.
\begin{enumerate}
\item A \textbf{model of $\mathsf{T}$ in $\mathcal{C}$ with respect to 
${\langle -, -\rangle}$}
is a pair $(C,\chi)$ consisting of an object $C$ of $\mathcal{C}$
and a monoid homomorphism $\chi\colon 
\mathsf{T}\longrightarrow\mathsf{End}_{\langle -, -\rangle}(C)$; that is, 
a morphism $\chi\colon T\longrightarrow {\langle C, C\rangle}$
in $\mathcal{M}$ making the following diagrams commute:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$I$};
      \node (TR) at (2,2)  {$T$};

      \node (BR) at (2,0) {${\langle C, C\rangle}$};

      \draw[->]  (TL) to node[auto,labelsize] {$e$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$\chi$} (BR);
      \draw[->] (TL) to node[auto,swap,labelsize](B) {$j_C$} (BR);

\end{tikzpicture} 
\qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$T\otimes T$};
      \node (TR) at (4,2)  {$T$};
      \node (BL) at (0,0) {${\langle C, C\rangle}\otimes{\langle C, C\rangle}$};
      \node (BR) at (4,0) {${\langle C, C\rangle}.$};

      \draw[->]  (TL) to node[auto,swap,labelsize] {$\chi\otimes\chi$} (BL);
      \draw[->]  (TL) to node[auto,labelsize] {$m$} (TR);
      \draw[->]  (BL) to node[auto,labelsize] {$M_{C,C,C}$} (BR);
      \draw[->]  (TR) to node[auto,labelsize](B) {$\chi$} (BR);

\end{tikzpicture} 
\end{equation*}
\item Let $(C,\chi)$ and $(C',\chi')$ be models of $\mathsf{T}$ in $\mathcal{C}$
with respect to ${\langle -, -\rangle}$. A \textbf{homomorphism from $(C,\chi)$ to 
$(C',\chi')$}
is a morphism $f\colon C\longrightarrow C'$ in $\mathcal{C}$ making the 
following diagram commute:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$T$};
      \node (TR) at (3,2)  {${\langle C', C'\rangle}$};
      \node (BL) at (0,0) {${\langle C, C\rangle}$};
      \node (BR) at (3,0) {${\langle C, C'\rangle}.$};

      \draw[->]  (TL) to node[auto,swap,labelsize] {$\chi$} (BL);
      \draw[->]  (TL) to node[auto,labelsize] {$\chi'$} (TR);
      \draw[->]  (BL) to node[auto,labelsize] {${\langle C, f\rangle}$} (BR);
      \draw[->]  (TR) to node[auto,labelsize](B) {${\langle f, C'\rangle}$} (BR);

\end{tikzpicture} 
\] 
\end{enumerate}
We denote the (large) category of models of $\mathsf{T}$ in $\mathcal{C}$ with 
respect to 
${\langle -, -\rangle}$ by ${\mathbf{Mod}(\mathsf{T},(\mathcal{C},{\langle -, -\rangle}))}$.

\label{def:2-cat_of_enrichments}
Let $\mathcal{M}=(\mathcal{M},I,\otimes)$ be a large monoidal category.
The (locally large) 2-category ${\mathscr{E}\!nrich(\mathcal{M})}$ of enrichments over $\mathcal{M}$ 
is defined as follows:
\begin{itemize}
\item An object is an enrichment $(\mathcal{C},{\langle -, -\rangle},j,M)$ over $\mathcal{M}$.
\item A 1-cell from $(\mathcal{C},{\langle -, -\rangle},j,M)$ to
$(\mathcal{C'},{\langle -, -\rangle}',j',M')$ is a functor 
$G\colon\mathcal{C}\longrightarrow\mathcal{C'}$ together with a natural transformation
$(g_{A,B}\colon{\langle A, B\rangle}\longrightarrow{\langle GA, GB\rangle}')_{A,B\in\mathcal{C}}$ 
making the 
following diagrams commute for all $A,B,C\in\mathcal{C}$:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$I$};
      \node (TR) at (4,1)  {${\langle C, C\rangle}$};
      \node (BR) at (4,-1) {${\langle GC, GC\rangle}'$};

      \draw[->] (TL) to node[auto,labelsize](T) {$j_C$} (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$g_{C,C}$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {$j'_{GC}$} 
      (BR);

\end{tikzpicture} 
\end{equation*}
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {${\langle B, C\rangle}\otimes{\langle A, B\rangle}$};
      \node (TR) at (6,1)  {${\langle A, C\rangle}$};
      \node (BL) at (0,-1) {${\langle GB, GC\rangle}'\otimes{\langle GA, GB\rangle}'$};
      \node (BR) at (6,-1) {${\langle GA, GC\rangle}'.$};

      \draw[->] (TL) to node[auto,labelsize](T) {$M_{A,B,C}$} 
      (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$g_{A,C}$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$g_{B,C}\otimes g_{A,B}$} 
      (BL);
      \draw[->]  (BL) to node[auto,labelsize] {$M'_{GA,GB,GC}$} (BR);

\end{tikzpicture} 
\end{equation*}
\item A 2-cell from $(G,g)$ to $(G',g')$, both from 
$(\mathcal{C},{\langle -, -\rangle},j,M)$ to $(\mathcal{C'},{\langle -, -\rangle}',j',$ $M')$, is a 
natural transformation $\theta\colon G\Longrightarrow G'$
making the following diagram commute for all $A,B\in\mathcal{C}$:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {${\langle A, B\rangle}$};
      \node (TR) at (4,2)  {${\langle GA, GB\rangle}'$};
      \node (BL) at (0,0) {${\langle G'A, G'B\rangle}'$};
      \node (BR) at (4,0) {${\langle GA, G'B\rangle}'.$};

      \draw[->] (TL) to node[auto,labelsize](T) {$g_{A,B}$} 
      (TR);
      \draw[->]  (TR) to node[auto,labelsize] {${\langle GA, \theta_B\rangle}'$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$g'_{A,B}$} 
      (BL);
      \draw[->]  (BL) to node[auto,labelsize] {${\langle \theta_A, G'B\rangle}'$} (BR);

\end{tikzpicture} \qedhere
\end{equation*}
\end{itemize}

\label{def:action_of_lax_on_enrichment}
Let $\mathcal{M}=(\mathcal{M},I_\mathcal{M},\otimes_\mathcal{M})$ and 
$\mathcal{N}=(\mathcal{N},I_\mathcal{N},\otimes_\mathcal{N})$ be large monoidal categories,
$F=(F,f_\cdot,f)\colon\mathcal{M}\longrightarrow\mathcal{N}$ be a lax monoidal 
functor,\footnote{In more detail, such a lax monoidal functor 
(also called monoidal functors in e.g.,~\cite{MacLane_CWM})
$(F,f_\cdot,f)$ consists of a functor $F\colon\mathcal{M}\longrightarrow\mathcal{N}$,
a morphism $f_\cdot\colon I_\mathcal{N}\longrightarrow FI_\mathcal{M}$
and a natural transformation $(f_{X,Y}\colon FY\otimes_\mathcal{N}FX\longrightarrow 
F(Y\otimes_\mathcal{M} X))_{X,Y\in\mathcal{M}}$ satisfying the suitable axioms.} 
$\mathcal{C}$ be a large category and ${\langle -, -\rangle}=({\langle -, -\rangle},j,M)$ be an 
enrichment of $\mathcal{C}$ over $\mathcal{M}$.
We define the enrichment $F_\ast({\langle -, -\rangle})=({\langle -, -\rangle}',j',M')$ 
of $\mathcal{C}$ over $\mathcal{N}$ as follows:
\begin{itemize}
\item The functor 
${\langle -, -\rangle}'\colon\mathcal{C}^{\mathrm{op}}\times\mathcal{C}\longrightarrow\mathcal{N}$
maps $(A,B)\in\mathcal{C}^{\mathrm{op}}\times\mathcal{C}$ to $F{\langle A, B\rangle}$.
\item The natural transformation $(j'_C\colon 
I_\mathcal{N}\longrightarrow{\langle C, C\rangle}')_{C\in\mathcal{C}}$
is defined by $j'_C=Fj_C\circ f_\cdot$:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (L) at (0,0)  {$I_\mathcal{N}$};
      \node (M) at (2,0)  {$FI_\mathcal{M}$};
      \node (R) at (4.5,0)  {$F{\langle C, C\rangle}$.};

      \draw[->]  (L) to node[auto,labelsize] {$f_\cdot$} (M);
      \draw[->]  (M) to node[auto,labelsize] {$Fj_C$} (R);
\end{tikzpicture} 
\]
\item The natural transformation $(M'_{A,B,C}\colon 
{\langle B, C\rangle}'\otimes_\mathcal{N}{\langle A, B\rangle}'\longrightarrow{\langle A, C\rangle}')_{A,
B,C\in\mathcal{C}}$
is defined by $M'_{A,B,C}=FM_{A,B,C}\circ f_{{\langle A, B\rangle},{\langle B, C\rangle}}$:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
