\label{def:oplax_action}
Let $\mathcal{M}=(\mathcal{M},I,\otimes)$ be a large monoidal category.
An \textbf{oplax action of $\mathcal{M}$} consists of:
\begin{itemize}
\item a large category $\mathcal{C}$;
\item a functor $\ast \colon \mathcal{M}\times\mathcal{C}\longrightarrow\mathcal{C}$;
\item a natural transformation $(\varepsilon_C\colon I\ast C\longrightarrow 
C)_{C\in\mathcal{C}}$;
\item a natural transformation 
$(\delta_{X,Y,C}\colon (Y\otimes X)\ast C\longrightarrow Y\ast (X\ast 
C))_{X,Y\in\mathcal{M},C\in\mathcal{C}},$\footnote{We have chosen to set 
$\delta_{X,Y,C}\colon (Y\otimes X)\ast C
\longrightarrow Y\ast (X\ast C)$ and not 
$\delta_{X,Y,C}\colon (X\otimes Y)\ast C
\longrightarrow X\ast (Y\ast C)$,
because the former agrees with 
the convention to write composition of morphisms in the
anti-diagrammatic order, which we adopt throughout 
this thesis.}
\end{itemize} 
making the following diagrams commute for all $X,Y,Z\in\mathcal{M}$
and $C\in\mathcal{C}$:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$(I\otimes X)\ast C$};
      \node (TR) at (4,1)  {$I\ast(X\ast C)$};
      \node (BR) at (4,-1) {$X\ast C$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\delta_{X,I,C}$} (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$\varepsilon_{X\ast C}$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {$\cong$} (BR);

\end{tikzpicture} 
\quad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$(X\otimes I)\ast C$};
      \node (TR) at (4,1)  {$X\ast(I\ast C)$};
      \node (BR) at (4,-1) {$X\ast C$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\delta_{I,X,C}$} (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$X\ast \varepsilon_{C}$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {$\cong$} (BR);

\end{tikzpicture} 
\end{equation*}
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$((Z\otimes Y)\otimes X)\ast C$};
      \node (TR) at (9,1)  {$(Z\otimes Y)\ast (X\ast C)$};
      \node (BL) at (0,-1) {$(Z\otimes (Y\otimes X))\ast C$};
      \node (BM) at (4.5,-1) {$Z\ast ((Y\otimes X)\ast C)$};
      \node (BR) at (9,-1) {$Z\ast (Y\ast (X\ast C)).$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\delta_{X,Z\otimes Y,C}$} 
      (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$\delta_{Y,Z,X\ast C}$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$\cong$} (BL);
      \draw[->]  (BL) to node[auto,labelsize] {$\delta_{Y\otimes X,Z,C}$} (BM);
      \draw[->] (BM) to node[auto,labelsize](B) {$Z\ast \delta_{X,Y,C}$} (BR);

\end{tikzpicture} 
\end{equation*}
We say that $(\mathcal{C},\ast,\varepsilon,\delta)$ is 
an oplax action of $\mathcal{M}$, or that $(\ast,\varepsilon,\delta)$ is 
an oplax action of $\mathcal{M}$ on $\mathcal{C}$.

\label{def:action_model}
Let $\mathcal{M}=(\mathcal{M},I,\otimes)$ be a large monoidal category,
$\mathsf{T}=(T,e,m)$ be a monoid object in $\mathcal{M}$,
$\mathcal{C}$ be a large category, and $\ast=(\ast,\varepsilon,\delta)$
be an oplax action of $\mathcal{M}$ on $\mathcal{C}$.
\begin{enumerate}
\item A \textbf{model of $\mathsf{T}$ in $\mathcal{C}$ with respect to $\ast$}
is a pair $(C,\gamma)$ consisting of an object $C\in\mathcal{C}$
and a morphism $\gamma\colon T\ast C\longrightarrow C$ in $\mathcal{C}$
making the following diagrams commute:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$I\ast C$};
      \node (TR) at (2,2)  {$T\ast C$};

      \node (BR) at (2,0) {${C}$};

      \draw[->]  (TL) to node[auto,labelsize] {$e\ast C$} (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$\gamma$} (BR);
      \draw[->] (TL) to node[auto,swap,labelsize](B) {$\varepsilon_C$} (BR);

\end{tikzpicture} 
\qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$(T\otimes T)\ast C$};
      \node (TR) at (5,2)  {$T\ast C$};
      \node (BL) at (0,0) {$T\ast (T\ast C)$};
      \node (BM) at (3,0) {$T\ast C$};
      \node (BR) at (5,0) {${C}.$};

      \draw[->]  (TL) to node[auto,swap,labelsize] {$\delta_{T,T,C}$} (BL);
      \draw[->]  (TL) to node[auto,labelsize] {$m\ast C$} (TR);
      \draw[->]  (BL) to node[auto,labelsize] {$T\ast \gamma$} (BM);
      \draw[->]  (BM) to node[auto,labelsize] {$\gamma$} (BR);
      \draw[->]  (TR) to node[auto,labelsize](B) {$\gamma$} (BR);

\end{tikzpicture} 
\end{equation*}
\item Let $(C,\gamma)$ and $(C',\gamma')$ be models of $\mathsf{T}$ in $\mathcal{C}$
with respect to $\ast$. A \textbf{homomorphism from $(C,\gamma)$ to 
$(C',\gamma')$}
is a morphism $f\colon C\longrightarrow C'$ in $\mathcal{C}$ making the 
following diagram commute:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,2)  {$T\ast C$};
      \node (TR) at (3,2)  {$T\ast C'$};
      \node (BL) at (0,0) {$C$};
      \node (BR) at (3,0) {$C'.$};

      \draw[->]  (TL) to node[auto,swap,labelsize] {$\gamma$} (BL);
      \draw[->]  (TL) to node[auto,labelsize] {$T\ast f$} (TR);
      \draw[->]  (BL) to node[auto,labelsize] {${f}$} (BR);
      \draw[->]  (TR) to node[auto,labelsize](B) {$\gamma'$} (BR);

\end{tikzpicture} 
\] 
\end{enumerate}
We denote the (large) category of models of $\mathsf{T}$ in $\mathcal{C}$ with 
respect to $\ast$ by ${\mathbf{Mod}(\mathsf{T},(\mathcal{C},\ast))}$.

Let $\mathcal{M}=(\mathcal{M},I,\otimes)$ be a large monoidal category.
The (locally large) 2-category ${\mathscr{A}\!ct_{\mathrm{oplax}}(\mathcal{M})}$ of oplax actions of $\mathcal{M}$
is defined as follows:
\begin{itemize}
\item An object is an oplax action $(\mathcal{C},\ast,\varepsilon,\delta)$ of 
$\mathcal{M}$.
\item A 1-cell from $(\mathcal{C},\ast,\varepsilon,\delta)$ to 
$(\mathcal{C'},\ast',\varepsilon',\delta')$ is a functor $G\colon \mathcal{C}
\longrightarrow\mathcal{C'}$ together with a natural transformation
$(g_{X,C}\colon X\ast' GC\longrightarrow G(X\ast C))_{X\in\mathcal{M},C\in\mathcal{C}}$
making the following diagrams commute for all $X,Y\in\mathcal{M}$ and $C\in\mathcal{C}$:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$I\ast' GC$};
      \node (TR) at (4,1)  {$G(I\ast C)$};
      \node (BR) at (4,-1) {$GC$};

      \draw[->] (TL) to node[auto,labelsize](T) {$g_{I,C}$} (TR);
      \draw[->] (TR) to node[auto,labelsize](R) {$G\varepsilon_C$} (BR);
      \draw[->]  (TL) to node[auto,labelsize,swap] (L) {$\varepsilon'_{GC}$} 
      (BR);

\end{tikzpicture} 
\end{equation*}
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
