      \node (TR) at (8,1)  {$G((Y\otimes X)\ast C)$};
      \node (BL) at (0,-1) {$Y\ast'(X\ast'GC)$};
      \node (BM) at (4,-1) {$Y\ast'G(X\ast C)$};
      \node (BR) at (8,-1) {$G(Y\ast (X\ast C)).$};

      \draw[->] (TL) to node[auto,labelsize](T) {$g_{Y\otimes X,C}$} 
      (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$G\delta_{X,Y,C}$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$\delta'_{X,Y,GC}$} (BL);
      \draw[->]  (BL) to node[auto,labelsize] {$Y\ast' g_{X,C}$} (BM);
      \draw[->] (BM) to node[auto,labelsize](B) {$g_{Y,X\ast C}$} (BR);

\end{tikzpicture} 
\end{equation*}
\item A 2-cell from $(G,g)$ to $(G',g')$, both from 
$(\mathcal{C},\ast,\varepsilon,\delta)$ to 
$(\mathcal{C'},\ast',\varepsilon',\delta')$,
is a natural transformation $\theta\colon G\Longrightarrow G'$
making the following diagram commute for all $X\in\mathcal{M}$
and $C\in\mathcal{C}$:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
