      \node (BR) at (4,0) {$G'(X\ast C).$};

      \draw[->] (TL) to node[auto,labelsize](T) {$g_{X,C}$} 
      (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$\theta_{X\ast C}$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$X\ast' \theta_C$} 
      (BL);
      \draw[->]  (BL) to node[auto,labelsize] {$g'_{X,C}$} (BR);

\end{tikzpicture} \qedhere
\end{equation*}
\end{itemize}

\label{def:action_of_oplax_on_oplax_action}
Let $\mathcal{M}=(\mathcal{M},I_\mathcal{M},\otimes_\mathcal{M})$ and 
$\mathcal{N}=(\mathcal{N},I_\mathcal{N},\otimes_\mathcal{N})$ be large monoidal categories,
$G=(G,g_\cdot,g)\colon\mathcal{N}\longrightarrow\mathcal{M}$ be an oplax monoidal 
functor,\footnote{Such an oplax functor consists of a functor 
$G\colon\mathcal{N}\longrightarrow\mathcal{M}$,
a morphism $g_\cdot\colon GI_\mathcal{N}\longrightarrow I_\mathcal{M}$
and a natural transformation $(g_{X,Y}\colon G(Y\otimes_\mathcal{N}X)
\longrightarrow GY\otimes_\mathcal{M} GX)_{X,Y\in\mathcal{N}}$ satisfying the suitable 
axioms.} 
$\mathcal{C}$ be a large category and $\ast=(\ast,\varepsilon,\delta)$ be an 
oplax action of $\mathcal{M}$ on $\mathcal{C}$.
We define the oplax action $G^\ast(\ast)=(\ast',\varepsilon',\delta')$ 
of $\mathcal{N}$ on $\mathcal{C}$ as follows:
\begin{itemize}
\item The functor 
$\ast'\colon\mathcal{N}\times\mathcal{C}\longrightarrow\mathcal{C}$
maps $(X,C)\in\mathcal{N}\times\mathcal{C}$ to $(GX)\ast C$.
\item The natural transformation $(\varepsilon'_C\colon 
I_\mathcal{N}\ast' C\longrightarrow C)_{C\in\mathcal{C}}$
is defined by $\varepsilon'_C=\varepsilon_C\circ (g_\cdot\ast C)$:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (L) at (0,0)  {$GI_\mathcal{N}\ast C$};
      \node (M) at (2.5,0)  {$I_\mathcal{M}\ast C$};
      \node (R) at (4.5,0)  {${C}$.};

      \draw[->]  (L) to node[auto,labelsize] {$g_\cdot\ast C$} (M);
      \draw[->]  (M) to node[auto,labelsize] {$\varepsilon_C$} (R);
\end{tikzpicture} 
\]
\item The natural transformation $(\delta'_{X,Y,C}\colon 
(Y\otimes_\mathcal{N}X)\ast' C\longrightarrow Y\ast'(X\ast' 
C))_{X,Y\in\mathcal{N},C\in\mathcal{C}}$
is defined by $\delta'_{X,Y,C}=\delta_{GX,GY,C}\circ (g_{X,Y}\ast C)$:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (L) at (0,0)  {$G(Y\otimes_\mathcal{N}X)\ast C$};
      \node (M) at (4.5,0)  {$(GY\otimes_\mathcal{M}GX)\ast C$};
      \node (R) at (9,0)  {$GY\ast(GX\ast{C})$.};

      \draw[->]  (L) to node[auto,labelsize] 
      {$g_{X,Y}\ast C$} (M);
      \draw[->]  (M) to node[auto,labelsize] {$\delta_{GX,GY,C}$} (R);
\end{tikzpicture} \qedhere
\]
\end{itemize}

\label{def:enrichr_olactl}
Let $\mathcal{M}$ be a large monoidal category. 
\begin{enumerate}
\item Let ${\mathscr{E}\!nrich^{\mathrm{r}}(\mathcal{M})}$ be the full sub-2-category of ${\mathscr{E}\!nrich(\mathcal{M})}$
consisting of all enrichments $(\mathcal{C},{\langle -, -\rangle},j,M)$ such that 
for each $C\in\mathcal{C}$, ${\langle C, -\rangle}$ is a right adjoint.
\item Let ${\mathscr{A}\!ct^{\mathrm{l}}_{\mathrm{oplax}}(\mathcal{M})}$ be the full sub-2-category of ${\mathscr{A}\!ct_{\mathrm{oplax}}(\mathcal{M})}$
consisting of all oplax actions $(\mathcal{C},\ast,\varepsilon,\delta)$
such that for each $C\in\mathcal{C}$, $-\ast C$ is a left adjoint.\qedhere
\end{enumerate}

\label{def:Day_conv}
Let $\mathcal{M}=(\mathcal{M},I,\otimes)$ be a large monoidal category.
The \textbf{convolution monoidal structure} 
$(\widehat{I},\mathbin{\widehat{\otimes}})$ on the presheaf category $\widehat{\mathcal{M}}
=[\mathcal{M}^{\mathrm{op}},\mathbf{SET}]$ is defined as follows.
\begin{itemize}
\item The unit object $\widehat{I}$ is the representable functor 
$\mathcal{M}(-,I)\colon \mathcal{M}^{\mathrm{op}}\longrightarrow\mathbf{SET}$.
\item Given $P,Q\in\widehat{\mathcal{M}}$, their monoidal product
$Q\mathbin{\widehat{\otimes}} P\colon \mathcal{M}^{\mathrm{op}}\longrightarrow\mathbf{SET}$ maps $Z\in\mathcal{M}$
to 
\begin{equation}
\label{eqn:Day_convolution}
(Q\mathbin{\widehat{\otimes}} P)(Z)=\int^{X,Y\in\mathcal{M}} \mathcal{M}(Z,Y\otimes X)
\times Q(Y)\times P(X).
\end{equation}
\qedhere
\end{itemize}

\label{def:metamodel}
Let $\mathcal{M}=(\mathcal{M},\otimes, I)$ be a metatheory.
A \textbf{metamodel of $\mathcal{M}$} consists of:
\begin{itemize}
