\[
((\overline{\phi}_{X,Y})_{A,B,C}\colon 
\Phi_Y(B,C)\times\Phi_X(A,B)
\longrightarrow\Phi_{Y\otimes X}(A,C))_{X,Y\in\mathcal{M},A,B,C\in\mathcal{C}},
\]
\end{itemize}
making the following diagrams commute 
for all $X,Y,Z\in\mathcal{M}$ and $A,B,C,D\in\mathcal{C}$:
