      \times(\alpha_{A,B})_{{\langle A, B\rangle}}$} (T);
      \draw[->] (L) to 
      node[auto,labelsize]{$(\alpha_{A,C})_{{\langle B, C\rangle}
      \otimes{\langle A, B\rangle}}^{-1}$}
