\item a natural transformation $(h_{N,N',M,M'}\colon H(N',M')\times 
H(N,M)\longrightarrow H(N'\otimes_\mathcal{N}
N,M'\otimes_\mathcal{M} M))_{N,N'\in\mathcal{N},M,M'\in\mathcal{M}}$
\end{itemize}
making the following diagrams commute for each $N,N',N''\in\mathcal{N}$
