In this case, the suitable 2-functors between 2-categories of metamodels
can be given either as ${\mathscr{M}\!\mathscr{M}\!od((\mathrm{Lan}_J)^\ast)}$ or ${\mathscr{M}\!\mathscr{M}\!od(([J,\mathbf{Set}])_\ast)}$ 
(and similarly for $J'$),
because $(\mathrm{Lan}_J)^\ast\cong ([J,\mathbf{Set}])_\ast$ in ${\mathscr{M}\!\mathscr{T\!H}}$.

\label{thm:str_sem_small}
Let $\mathcal{M}$ be a metatheory, $\mathcal{C}$ be a large category and 
$\Phi=(\Phi,\overline{\phi}_\cdot,\overline{\phi})$ 
be a metamodel of $\mathcal{M}$ in $\mathcal{C}$.
The functors $\mathrm{Sem}$ and $\mathrm{Str}$ defined above
form an adjunction:
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(11) at (0,0) 
      {${\mathbf{Th}(\widehat{\mathcal{M}})}^{\mathrm{op}}$};
      \node(22) at (4,0) {${\mathbf{CAT}}/\mathcal{C}$.};

      \draw [->,transform canvas={yshift=5pt}]  (22) to node 
      [auto,swap,labelsize]{$\mathrm{Str}$} (11);
      \draw [->,transform canvas={yshift=-5pt}]  (11) to node 
      [auto,swap,labelsize]{$\mathrm{Sem}$} (22);
      \path (11) to node[midway](m){} (22); 

      \node at (m) [labelsize,rotate=90] {$\vdash$};
\end{tikzpicture}
\]

We show that there are bijections
\[{\mathbf{Th}(\widehat{\mathcal{M}})}(\mathsf{P},\mathrm{Str}(V))\cong
({\mathbf{CAT}}/\mathcal{C})(V,\mathrm{Sem}(\mathsf{P}))\]
natural in $\mathsf{P}=(P,e,m)\in{\mathbf{Th}(\widehat{\mathcal{M}})}$ and $(V\colon 
\mathcal{A}\longrightarrow\mathcal{C})\in{\mathbf{CAT}}/\mathcal{C}$.

In fact, we show that the following three types of data naturally 
correspond to each other.
\begin{enumerate}
\item A morphism $\alpha\colon \mathsf{P}\longrightarrow\mathrm{Str}(V)$ in 
${\mathbf{Th}(\widehat{\mathcal{M}})}$; that is, a natural transformation 
\[
(\alpha_X\colon P(X)\longrightarrow P^{(V)}(X))_{X\in\mathcal{M}}
\]
making the suitable diagrams commute.
\item A natural transformation \[
(\xi_{A,X}\colon P(X)\longrightarrow \Phi_X(VA,VA))_{X\in\mathcal{M},
A\in\mathcal{A}}
\]
making the following diagrams commute for each $A\in\mathcal{A}$ and 
$X,Y\in\mathcal{M}$:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
