      \draw[->]  (TR) to node[auto,labelsize] {$\xi_{A,I}$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] 
      {$(\overline{\phi}_\cdot)_{VA}$} 
      (BR);

\end{tikzpicture} 
\quad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1)  {$P(Y)\times P(X)$};
      \node (TR) at (5.5,1)  {$P({Y\otimes X})$};
      \node (BL) at (0,-1) {$\Phi_Y(VA,VA)\times \Phi_X(VA,VA)$};
      \node (BR) at (5.5,-1) {$\Phi_{Y\otimes X}(VA,VA).$};

      \draw[->] (TL) to node[auto,labelsize](T) 
      {$\overline{m}_{X,Y}$} 
      (TR);
      \draw[->]  (TR) to node[auto,labelsize] {$\xi_{A,Y\otimes X}$} (BR);
      \draw[->]  (TL) to node[auto,swap,labelsize] {$\xi_{A,Y}\times 
      \xi_{A,X}$} 
      (BL);
      \draw[->]  (BL) to node[auto,labelsize] 
