is equivalent to saying that ${\mathrm{ob}(F)}$ extends to a functor 
$F\colon \mathcal{A}\longrightarrow{\mathbf{Mod}(\mathsf{P},(\mathcal{C},\Phi))}$
by mapping each morphism $f$ in $\mathcal{A}$ to $Vf$.

\label{def:psd_dbl_cat}
A \textbf{pseudo double category} $\mathbb{D}$ consists of the following data.
\begin{description}
\item[(DD1)] A category $\mathbb{D}_0$, whose objects are called
\textbf{objects} of $\mathbb{D}$ and whose 
morphisms \textbf{vertical morphisms} of $\mathbb{D}$.
\item[(DD2)] A category $\mathbb{D}_1$, whose objects are called
\textbf{horizontal morphisms} of $\mathbb{D}$ and whose 
morphisms \textbf{squares} of $\mathbb{D}$.
\item[(DD3)] Functors 
\begin{align*}
s,t&\colon \mathbb{D}_1\longrightarrow\mathbb{D}_0,\\
I&\colon \mathbb{D}_0\longrightarrow \mathbb{D}_1,\\
\otimes&\colon\mathbb{D}_2\longrightarrow\mathbb{D}_1,
\end{align*}
where $\mathbb{D}_2$ is the pullback
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1.5)  {$\mathbb{D}_2$};
      \node (TR) at (1.5,1.5)  {$\mathbb{D}_1$};
      \node (BL) at (0,0) {$\mathbb{D}_1$};
      \node (BR) at (1.5,0) {$\mathbb{D}_0$};

      \draw[->] (TL) to node[auto,labelsize](T) {$\pi_2$} (TR);
      \draw[->] (TR) to node[auto,labelsize] {$t$} (BR);
      \draw[->] (TL) to node[auto,swap,labelsize] {$\pi_1$} (BL);
      \draw[->] (BL) to node[auto,swap,labelsize](B) {$s$} (BR);

      \draw (TL)++(0.2,-0.6)-- ++ (0.4,0) -- ++(0,0.4);
\end{tikzpicture}
\]
of categories.
\item[(DD4)] Natural isomorphisms with components
\begin{align*}
\mathfrak{a}_{X,Y,Z}&\colon (Z\otimes Y)\otimes X \longrightarrow Z\otimes(Y\otimes 
X),\\
\mathfrak{l}_X&\colon I_B\otimes X\longrightarrow X, \\
\mathfrak{r}_X&\colon X\otimes I_A\longrightarrow X
\end{align*}
in $\mathbb{D}_1$, where $(Z,Y,X)\in \mathbb{D}_3$
which is the pullback
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1.5)  {$\mathbb{D}_3$};
      \node (TR) at (1.5,1.5)  {$\mathbb{D}_1$};
      \node (BL) at (0,0) {$\mathbb{D}_2$};
      \node (BR) at (1.5,0) {$\mathbb{D}_0$};

      \draw[->] (TL) to node[auto,labelsize](T) {} (TR);
      \draw[->] (TR) to node[auto,labelsize] {$t$} (BR);
      \draw[->] (TL) to node[auto,swap,labelsize] {} (BL);
      \draw[->] (BL) to node[auto,swap,labelsize](B) {$s\circ \pi_2$} (BR);

      \draw (TL)++(0.2,-0.6)-- ++ (0.4,0) -- ++(0,0.4);
\end{tikzpicture}
\]
of categories and $X\in \mathbb{D}_1$ with $s(X)=A$ and $t(X)=B$.
\end{description}
These data are subject to the following axioms.
\begin{description}
\item[(DA1)] The diagrams
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1.5)  {$\mathbb{D}_0$};
      \node (BL) at (0,0) {$\mathbb{D}_1$};
      \node (BR) at (1.5,0) {$\mathbb{D}_0$};
      \node (BLL) at (-1.5,0) {$\mathbb{D}_0$};

      \draw[->] (TL) to node[auto,labelsize](T) {${\mathrm{id}_{}}$} (BR);
      \draw[->] (TL) to node[auto,labelsize] {$I$} (BL);
      \draw[->] (BL) to node[auto,swap,labelsize](B) {$t$} (BR);
      \draw[->] (TL) to node[auto,swap,labelsize](T) {${\mathrm{id}_{}}$} (BLL);
      \draw[->] (BL) to node[auto,labelsize](B) {$s$} (BLL);
\end{tikzpicture}
\ \qquad
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node (TL) at (0,1.5)  {$\mathbb{D}_2$};
      \node (BL) at (0,0) {$\mathbb{D}_1$};
      \node (BR) at (1.5,0) {$\mathbb{D}_0$};
      \node (BLL) at (-1.5,0) {$\mathbb{D}_0$};

      \draw[->] (TL) to node[auto,labelsize](T) {$t\circ \pi_1$} (BR);
      \draw[->] (TL) to node[auto,labelsize] {$\otimes$} (BL);
      \draw[->] (BL) to node[auto,swap,labelsize](B) {$t$} (BR);
      \draw[->] (TL) to node[auto,swap,labelsize](T) {$s\circ \pi_2$} (BLL);
      \draw[->] (BL) to node[auto,labelsize](B) {$s$} (BLL);
\end{tikzpicture}
\]
commute (on the nose).
\item[(DA2)] The morphisms $s(\mathfrak{a}_{X,Y,Z}),s(\mathfrak{l}_X)$ and 
$s(\mathfrak{r}_X)$
are equal to ${\mathrm{id}_{A}}$ for all $(Z,Y,X)$ $\in\mathbb{D}_3$ 
and $X\in\mathbb{D}_1$, where $A=s(X)$.
Similarly for $t$.
\item[(DA3)] The coherence axioms (triangle and pentagon) for $\mathfrak{a},\mathfrak{l}$ and 
$\mathfrak{r}$.\qedhere
\end{description}

\label{ex:H_construction}
Let $\mathscr{B}$ be a bicategory.
This induces a pseudo double category $\mathbb{H}\mathscr{B}$, given as follows:
\begin{itemize}
\item an object of $\mathbb{H}\mathscr{B}$ is an object of $\mathscr{B}$;
\item all vertical morphisms of $\mathbb{H}\mathscr{B}$ are vertical identity 
morphisms;
\item a horizontal morphism of $\mathbb{H}\mathscr{B}$ is a 1-cell of $\mathscr{B}$;
\item a square of $\mathbb{H}\mathscr{B}$ is a 2-cell of $\mathscr{B}$.
\end{itemize} 
The isomorphisms $\mathfrak{a},\mathfrak{l}$ and $\mathfrak{r}$ of $\mathbb{H}\mathscr{B}$ is given by
the corresponding iso-2-cells of $\mathscr{B}$.

Conversely, for any pseudo double category $\mathbb{D}$,
we obtain a bicategory $\mathscr{H}\mathbb{D}$ given as follows:
\begin{itemize}
\item an object of $\mathscr{H}\mathbb{D}$ is an object of $\mathbb{D}$;
\item a 1-cell of $\mathscr{H}\mathbb{D}$ is a horizontal morphism of $\mathbb{D}$;
\item a 2-cell of $\mathscr{H}\mathbb{D}$ is a square in $\mathbb{D}$ whose 
horizontal source and target are both vertical identity morphisms.\qedhere
\end{itemize}

We define the pseudo double category ${\mathbb{PROF}}$ as follows.
\begin{itemize}
