\label{thm:free_nV_cat_monad_cart}
For each natural number $n$, the free strict $n$-dimensional $\mathcal{V}$-category 
monad $\mathsf{T}^{(n)}$ is cartesian.

\label{def:contraction}
Let $\mathcal{C}$ be a category, ${J}$ a set, and 
$\mathcal{F}=(f_j\colon A_j\longrightarrow B_j)_{j\in {J}}$ a
${J}$-indexed family of morphisms in $\mathcal{C}$.
\begin{enumerate}
\item A \textbf{contraction} (with respect to $\mathcal{F}$) 
on a morphism $g\colon C\longrightarrow D$
in $\mathcal{C}$ is a $J$-indexed family of functions $(\kappa_j)_{j\in J}$
such that for each $j\in J$, $\kappa_j$
assigns to every 
pair of morphisms $(h,k)$ in $\mathcal{V}$ which
makes the perimeter of (\ref{eqn:diagonal_filler}) commute,
a morphism $\kappa_j(h,k)$ making the whole diagram 
(\ref{eqn:diagonal_filler})
commute.
\begin{equation}\label{eqn:diagonal_filler}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,1) {$A_j$};
      \node(1) at (2,1) {$C$};
      \node(2) at (0,-1) {$B_j$};
      \node(3) at (2,-1) {$D$};

      \draw [->] 
            (0) to node (t)[auto,labelsize] {$h$} 
            (1);
      \draw [->] 
            (1) to node (r)[auto,labelsize] {$g$} 
            (3);
      \draw [->] 
            (0) to node (l)[auto,swap,labelsize] {$f_j$} 
            (2);
      \draw [->] 
            (2) to node (b)[auto,swap,labelsize] {$k$} 
            (3);  
      \draw [->] 
            (2) to node [midway,fill=white,labelsize] {$\kappa_j(h,k)$} (1);
\end{tikzpicture}
\end{equation}
\item A \textbf{map of morphisms with contractions} from $(g\colon 
C\longrightarrow D, (\kappa)_{j\in J})$
to $(g'\colon C'\longrightarrow D',(\kappa'_j)_{j\in J})$
is a map of morphisms $(u\colon C\longrightarrow C',v\colon D\longrightarrow 
D')$
from $g$ to $g'$ which commutes with contractions:
for each $j\in J$ and $(h,k)$ in the domain of $\kappa_j$,
$u\circ \kappa_j(h,k)=\kappa'_j(u\circ h, v\circ k)$.
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,2) {$A_j$};
      \node(1) at (2,2) {$C$};
      \node(2) at (0,0) {$B_j$};
      \node(3) at (2,0) {$D$};
      \node(4) at (4,2) {$C'$};
      \node(5) at (4,0) {$D'$};


      \draw [->] 
            (0) to node (t)[auto,labelsize] {$h$} 
            (1);
      \draw [->] 
            (1) to node (r)[auto,near end,labelsize] {$g$} 
            (3);
      \draw [->] 
            (0) to node (l)[auto,swap,labelsize] {$f_j$} 
            (2);
      \draw [->] 
            (2) to node (b)[auto,swap,labelsize] {$k$} 
            (3);  
      \draw [->] 
            (1) to node (b)[auto,labelsize] {$u$} 
            (4);  
      \draw [->] 
            (3) to node (b)[auto,swap,labelsize] {$v$} 
            (5);  
      \draw [->] 
            (4) to node (b)[auto,labelsize] {$g'$} 
            (5);  

      \draw [->] 
            (2) to node [midway,fill=white,labelsize] {$\kappa_j(h,k)$} (1);
      \draw [->] 
            (2) to node [near end,fill=white,labelsize] {$\kappa'_j(u 
            h,v k)$} (4);
\end{tikzpicture}
\end{equation*}
\end{enumerate}
We write the category of morphisms in $\mathcal{C}$ with contractions (with respect 
to $\mathcal{F}$) as ${\mathbf{Contr}(\mathcal{F})}$.
Note that we have the evident forgetful functor 
$V\colon{\mathbf{Contr}(\mathcal{F})}\longrightarrow\mathcal{C}^{\mathbf{2}}$
where $\mathbf{2}$ denotes the arrow category (i.e., the ordinal $\mathbf{2}$ seen as 
a category) and $\mathcal{C}^\mathbf{2}=[\mathbf{2},\mathcal{C}]$ is the functor category.
